#include <stdio.h>
#define CONCAT(a, b)  a##b
#define MAKE_VAR(n)   int var_##n = n
#define GENERIC_ADD(type) type##_add
int int_add(int a, int b) { return a + b; }
int main(void) {
    int xy = CONCAT(1, 2);          /* 1##2 = 12? 实际是记号 12 作为整数字面量 */
    printf("CONCAT(1,2) = %d\n", xy);
    MAKE_VAR(7);                    /* int var_7 = 7; */
    printf("var_7 = %d\n", var_7);
    printf("GENERIC_ADD(int) 指向 %p (函数 int_add)\n", (void*)GENERIC_ADD(int));
    return 0;
}
